          {isOtpStep
            ? 'Подтверждение'
            : isRegisterMode
              ? 'Регистрация'
              : 'Вход'}
        </p>

        <h1 className="text-2xl font-semibold">
          {isOtpStep
            ? 'Введите код'
            : isRegisterMode
              ? 'Создать профиль DNA'
              : 'Войти в профиль'}
        </h1>

        <p className="text-sm leading-6 text-muted-foreground">
          {isOtpStep
            ? `Мы отправили код на ${value.login}. Введите его ниже.`
            : 'Покупать можно без регистрации. Аккаунт нужен для истории заказов, кешбэка, реферальной системы и заработка.'}
        </p>
      </header>

      {!isOtpStep && (
        <div className="mt-6 grid grid-cols-2 gap-1 rounded-xl bg-muted p-1">
          {authorizationModeItems.map((item) => {
            const isActive = mode === item.mode;

            return (
              <Button
                key={item.mode}
                type="button"
                variant={isActive ? 'default' : 'ghost'}
                className="h-9"
                onClick={() => onModeChange(item.mode)}
              >
                {item.label}
              </Button>
            );
          })}
        </div>
      )}

      <form
        onSubmit={handleSubmit}
        className="mt-6 space-y-6"
        autoComplete="off"
      >
        <div className="space-y-4">
          {isOtpStep ? (
            <>
              <FormInputField
                required
                type="text"
                inputMode="numeric"
                label="Код подтверждения"
                value={value.otpCode}
                placeholder="000000"
                autoComplete="one-time-code"
                onChange={getInputChangeHandler('otpCode')}
              />
            </>
          ) : (
            <>
              {isRegisterMode && (
                <FormInputField
                  required
                  label="Имя аккаунта"
                  value={value.nickname}
                  placeholder=""
                  autoComplete="off"
                  onChange={getInputChangeHandler('nickname')}
                />
              )}

              <FormInputField
                required
                type="text"
                inputMode="email"
                label="Email или телефон"
                value={value.login}
                placeholder=""
                autoComplete="username"
                onChange={getInputChangeHandler('login')}
              />
            </>
          )}
        </div>

        {errorMessage && (
          <p className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">
            {errorMessage}
          </p>
        )}

        {isOtpStep ? (
          <div className="flex flex-col gap-3">
            <Button
              type="submit"
