model User {
  id             String    @id @default(uuid())
  email          String?
  nickname       String
  nicknameSuffix String    @unique @default(dbgenerated("gen_random_uuid()"))
  firstName      String?
  lastName       String?
  role           UserRole  @default(DEFAULT)
  createdAt      DateTime  @default(now())
  updatedAt      DateTime  @updatedAt
  deletedAt      DateTime?

  passwordHash String?
  oauthProvider String?
  oauthProviderId String?

  patronymic   String?
  phone        String?
  referralCode String?

  avatarId String?
  avatar   Image?  @relation("UserAvatar", fields: [avatarId], references: [id])

  @@unique([oauthProvider, oauthProviderId])
  @@index([phone])

  cartItems  CartItem[]
  orders     Order[]
  ads        Ad[]
  favourites Favourite[]

  invitedReferrals Referral[] @relation("Inviter")
  receivedReferral Referral?  @relation("Invited")
  balance          Balance?
}

model OtpCode {
  id        String   @id @default(uuid())
  login     String
  type      String
  code      String
  expiresAt DateTime
  createdAt DateTime @default(now())

  @@index([login])
  @@index([code])
